            },
            "children": [
              {
                "kind": "list",
                "id": "messages",
                "props": {
                  "ordered": true,
                  "state": "ready"
                },
                "slots": {
                  "empty": [
                    {
                      "kind": "text",
                      "id": "no-messages",
                      "children": [
                        "No messages."
                      ]
                    }
                  ]
                },
                "children": [
                  {
                    "kind": "each",
                    "id": "message-each",
                    "props": {
                      "as": "message",
                      "in": {
                        "bind": "$.messages"
                      }
                    },
                    "children": [
                      {
                        "kind": "item",
                        "id": "message",
                        "props": {
                          "text": {
                            "bind": "$message.subject"
                          }
                        },
                        "on": {
                          "press": "inbox.open"
                        }
                      }
                    ]
                  }
                ]
              }
            ]
          },
          {
            "kind": "tab",
            "id": "tab-drafts",
            "props": {
              "label": {
                "bind": "$.labels.drafts"
              }
            },
            "children": [
              {
                "kind": "list",
                "id": "drafts",
                "props": {
                  "state": "empty"
                },
                "slots": {
                  "empty": [
                    {
                      "kind": "stack",
                      "id": "drafts-empty",
                      "props": {
                        "align": "center",
                        "direction": "column",
                        "gap": {
                          "token": "space.sm"
                        }
                      },
                      "children": [
                        {
                          "kind": "text",
                          "id": "no-drafts",
                          "children": [
                            "No drafts."
                          ]
                        },
                        {
                          "kind": "text",
                          "id": "no-drafts-hint",
                          "children": [
                            "Messages you start appear here."
                          ]
                        }
                      ]
                    }
                  ]
                }
              }
            ]
          },
          {
            "kind": "tab",
            "id": "tab-sent",
            "props": {
              "label": "Sent"
            },
            "children": [
              {
                "kind": "list",
                "id": "sent",
                "props": {
                  "state": "loading"
                },
                "children": [
                  {
                    "kind": "item",
                    "id": "sent-loading",
                    "children": [
                      "Loading…"
                    ]
                  }
                ]
              }
            ]
          }
        ]
      },
      {
        "kind": "menu",
        "id": "message-actions",
        "props": {
          "label": "Message actions"
        },
        "children": [
          {
            "kind": "menu-item",
            "id": "archive",
            "props": {
              "text": {
                "bind": "$.labels.archive"
              }
            },
            "on": {
              "press": "inbox.archive"
            }
          },
          {
            "kind": "menu-item",
            "id": "delete",
            "props": {
              "disabled": {
                "bind": "$.selection",
                "not": true
              }
            },
            "on": {
              "press": "inbox.delete"
            },
            "children": [
              "Delete"
            ]
          }
        ]
      },
      {
        "kind": "dialog",
        "id": "compose",
        "props": {
          "label": "New message",
          "modal": false,
          "open": {
            "bind": "$.composing"
          }
        },
        "on": {
          "close": "inbox.closeCompose"
        },
        "slots": {
          "actions": [
            {
              "kind": "button",
              "id": "send",
              "props": {
                "variant": "primary"
              },
              "on": {
                "press": "inbox.send"
              },
              "children": [
                "Send"
              ]
            }
          ]
        },
        "children": [
          {
            "kind": "form",
            "id": "compose-form",
            "props": {
              "state": "submitting"
            },
            "on": {
              "submit": "inbox.send"
            },
            "children": [
              {
                "kind": "field",
                "id": "to",
                "props": {
                  "label": "To",
                  "type": "email",
                  "value": {
                    "bind": "$.draft.to"
                  }
                }
              },
              {
                "kind": "field",
                "id": "body",
                "props": {
                  "label": "Message",
                  "type": "multiline",
                  "value": {
                    "bind": "$.draft.body"
                  }
                }
              }
            ]
          }
        ]
      }
    ]
  }
}

{
  "weft": "0.1",
  "root": {
    "kind": "screen",
    "id": "account",
    "props": {
      "label": "Edit account"
    },
    "children": [
      {
        "kind": "heading",
        "id": "title",
        "props": {
          "level": 1
        },
        "children": [
          "Edit account"
        ]
      },
      {
        "kind": "form",
        "id": "account-form",
        "props": {
          "label": "Account",
          "state": "invalid"
        },
        "on": {
          "submit": "account.save"
        },
        "slots": {
          "footer": [
            {
              "kind": "button",
              "id": "save",
              "props": {
                "state": "busy",
                "submit": true,
                "variant": "primary"
              },
              "children": [
                "Save"
              ]
            },
            {
              "kind": "button",
              "id": "cancel",
              "props": {
                "state": "idle",
                "text": {
                  "bind": "$.labels.cancel"
                },
                "variant": "secondary"
              },
              "on": {
                "press": "account.cancel"
              }
            },
            {
              "kind": "link",
              "id": "help",
              "props": {
                "href": "https://example.com/help",
                "text": {
                  "bind": "$.labels.help"
                }
              }
            }
          ]
        },
        "children": [
          {
            "kind": "field",
            "id": "name",
            "props": {
              "label": "Full name",
              "placeholder": "Ada Lovelace",
              "state": "valid",
              "type": "text",
              "value": {
                "bind": "$.account.name"
              }
            },
            "on": {
              "change": "account.edit"
            }
          },
          {
            "kind": "field",
            "id": "age",
            "props": {
              "error": {
                "bind": "$.errors.age"
              },
              "label": "Age",
              "state": "invalid",
              "type": "number",
              "value": {
                "bind": "$.account.age"
              }
            }
          },
          {
            "kind": "field",
            "id": "handle",
            "props": {
              "disabled": {
                "bind": "$.account.locked"
              },
              "label": "Handle",
              "placeholder": "{handle}",
              "value": {
                "bind": "$.account.handle"
              }
            }
          },
          {
            "kind": "field",
            "id": "bio",
            "props": {
              "label": "Bio",
              "type": "multiline",
              "value": {
                "bind": "$.account.bio"
              }
            }
          },
          {
            "kind": "field",
            "id": "email",
            "props": {
              "disabled": true,
              "label": "Email",
              "type": "email",
              "value": {
                "bind": "$.account.email"
              }
            }
          },
          {
            "kind": "checkbox",
            "id": "newsletter",
            "props": {
              "checked": {
                "bind": "$.account.newsletter"
              },
              "label": "Send me the newsletter"
            },
            "on": {
              "change": "account.edit"
            }
          },
          {
            "kind": "checkbox",
            "id": "terms",
            "props": {
              "checked": true,
              "disabled": true,
              "label": "Terms accepted"
            }
          },
          {
            "kind": "switch",
            "id": "public",
            "props": {
              "checked": {
                "bind": "$.account.public"
              },
              "disabled": {
                "bind": "$.account.verified",
                "not": true
              },
              "label": "Public profile"
            },
            "on": {
              "change": "account.edit"
            }
          },
          {
            "kind": "radio-group",
            "id": "plan",
            "props": {
              "label": "Plan",
              "value": {
                "bind": "$.account.plan"
              }
            },
            "on": {
              "change": "account.edit"
            },
            "children": [
              {
                "kind": "radio",
                "id": "plan-free",
                "props": {
                  "value": "free"
                },
                "children": [
                  "Free"
                ]
              },
              {
                "kind": "radio",
                "id": "plan-pro",
                "props": {
                  "text": {
                    "bind": "$.labels.pro"
                  },
                  "value": "pro"
                }
              },
              {
                "kind": "radio",
                "id": "plan-team",
                "props": {
                  "disabled": true,
                  "value": "team"
                },
                "children": [
                  "Team"
                ]
              }
            ]
          },
          {
            "kind": "select",
            "id": "language",
            "props": {
              "disabled": {
                "bind": "$.account.locked"
              },
              "label": "Language",
              "value": {
                "bind": "$.account.language"
              }
            },
            "on": {
              "change": "account.edit"
            },
            "children": [
              {
                "kind": "option",
                "id": "language-en",
                "props": {
                  "value": "en"
                },
                "children": [
                  "English"
                ]
              },
              {
                "kind": "option",
                "id": "language-fr",
                "props": {
                  "text": {
                    "bind": "$.labels.french"
                  },
                  "value": "fr"
                }
              }
            ]
          },
          {
            "kind": "text",
            "id": "internal",
            "props": {
              "hidden": true
            },
            "children": [
              "Internal note: never shown."
            ]
          },
          {
            "kind": "alert",
            "id": "saved",
            "props": {
              "hidden": {
                "bind": "$.saved",
                "not": true
              },
              "tone": "success"
            },
            "children": [
              "Your changes were saved."
            ]
          }
        ]
      }
    ]
  }
}
